221	      && !(typeof decl.invocation_endpoint === 'string' && /^[a-z0-9]+(-[a-z0-9]+)*$/.test(decl.invocation_endpoint))) {
222	    bad('"invocation_endpoint" is not a kebab-case endpoint name', 'name a key from the repo\'s taskScheduler.agenticTaskInvocationEndpoints map, e.g. "fleet" — never a URL');
223	  }
224	
225	  // The repo Actions secrets this task needs configured (DESIGN §9). Purely
226	  // DECLARATIVE — like a pack's adoption `questions`, its job is to drive the ask
227	  // (adoption interactively, the scheduler by owner issue), not to gate anything
228	  // here. So the only shape asserted is "a list of names"; whether the repo has
229	  // actually configured them is a fact about the repo, answered where the secrets
230	  // bundle is readable, never at author time.
231	  if (decl.required_secrets !== undefined
232	      && !(Array.isArray(decl.required_secrets) && decl.required_secrets.every((s) => typeof s === 'string' && s.trim() !== ''))) {
