1	// The task-janitor's code-work — the whole task (agent_model: none). The ONE
2	// home of dispatch-issue recovery and health review, moved out of the
3	// scheduler's hourly run (owner, 2026-08-06: scheduler creates, executor
4	// executes its one issue, janitor cleans up). This file is the I/O shell; the
5	// verdicts are the pure rules in the vendored engine (dispatch.mjs), so what
6	// counts as stale, dead or lost is decided in exactly one place.
7	//
8	// Three backstops, in this order:
9	//   1. STALE — a dispatch open past ~2 of its own scheduling periods →
10	//      escalation comment, drop the ready label, add `needs-human`. Once — an
11	//      already-escalated issue is never re-announced.
12	//   2. DEAD CLAIM — `agent-running` with no activity for ~3h → the session that
13	//      claimed it died; comment, drop `agent-running`, add `needs-human`.
14	//   3. RE-ARM — armed but untouched past the grace window → the trigger event
15	//      was lost, so remove and re-add its ready label to emit a fresh one.
16	// Stale wins over re-arm, so an issue converging to triage is never put back
17	// into circulation.
18	//
19	// The daily cadence is a stated trade (it was hourly when it lived in the
20	// scheduler): a lost trigger event or a dead claim now waits up to a day for
21	// recovery. That is the price of the responsibility split, and the owner chose
22	// it — recurring recovery is cleanup, and cleanup is nobody's job but this one.
23	//
24	// It ends with a HEALTH REVIEW: one line per open dispatch state, so the run
25	// log answers "how is the task machinery doing" at a glance.
26	
27	import { pathToFileURL } from 'node:url';
28	import {
29	  staleDispatchIssues, staleEscalationComment, staleClaimedDispatchIssues, staleClaimComment,
30	  rearmDispatchIssues, readyLabelOn, DISPATCH_PREFIX, NEEDS_HUMAN_LABEL, AGENT_RUNNING_LABEL,
31	  SCHEDULER_LABELS,
32	} from '../../../claudinite-tasks/dispatch.mjs';
33	import { makeGh } from '../../../claudinite-tasks/signals/gh.mjs';
34	import { ensureLabels } from '../../../claudinite-tasks/github.mjs';
35	
36	const item = process.env.CLAUDINITE_ITEM || '';
37	const log = (s) => console.log(`task-janitor${item ? ` [#${item}]` : ''}: ${s}`);
38	
39	// Every OPEN dispatch issue in the repo, with the labels / age / comment count
40	// the rules read. Repo-wide and open-only — the scheduler's own per-family
41	// state=all search (its filing guards) is a different question.
42	export async function openDispatchIssues(gh, repo) {
43	  const q = encodeURIComponent(`repo:${repo} is:issue is:open in:title "${DISPATCH_PREFIX}"`);
44	  const { status, json } = await gh(`/search/issues?q=${q}&per_page=100`);
45	  if (status !== 200 || !Array.isArray(json?.items)) {
46	    throw new Error(`could not list open dispatch issues: search returned ${status}`);
47	  }
48	  return json.items.map((i) => ({
49	    number: i.number, title: i.title, labels: i.labels ?? [],
50	    created_at: i.created_at, updated_at: i.updated_at, comments: i.comments ?? 0,
51	  }));
52	}
53	
54	// The sweep, injectable for tests: `gh` is the Action-token REST client.
55	export async function sweep(gh, repo, now) {
56	  const open = await openDispatchIssues(gh, repo);
57	  const result = { open: open.length, stale: [], deadClaims: [], rearmed: [] };
58	  const stale = staleDispatchIssues(open, now);
59	  const staleNumbers = new Set(stale.map((i) => i.number));
60	  const deadClaims = staleClaimedDispatchIssues(open, now).filter((i) => !staleNumbers.has(i.number));
61	  const rearm = rearmDispatchIssues(open, now);
62	
63	  if (stale.length || deadClaims.length || rearm.length) {
64	    // Applying a label 422s when it does not exist, so guarantee them first — a
65	    // quiet repo never gets here, so this costs nothing on the common path.
66	    await ensureLabels(gh, repo, SCHEDULER_LABELS);
67	  }
68	
69	  const escalate = async (issue, body, dropLabel) => {
70	    await gh(`/repos/${repo}/issues/${issue.number}/comments`, { method: 'POST', body: { body } });
71	    if (dropLabel) await gh(`/repos/${repo}/issues/${issue.number}/labels/${encodeURIComponent(dropLabel)}`, { method: 'DELETE' });
72	    await gh(`/repos/${repo}/issues/${issue.number}/labels`, { method: 'POST', body: { labels: [NEEDS_HUMAN_LABEL] } });
73	  };
74	
75	  for (const issue of stale) {
76	    await escalate(issue, staleEscalationComment(issue), readyLabelOn(issue));
77	    log(`escalated stale dispatch #${issue.number} to ${NEEDS_HUMAN_LABEL}`);
78	    result.stale.push(issue.number);
79	  }
80	  for (const issue of deadClaims) {
81	    await escalate(issue, staleClaimComment(issue), AGENT_RUNNING_LABEL);
82	    log(`reclaimed dead ${AGENT_RUNNING_LABEL} claim on #${issue.number} → ${NEEDS_HUMAN_LABEL}`);
83	    result.deadClaims.push(issue.number);
84	  }
85	  for (const issue of rearm) {
86	    const ready = readyLabelOn(issue);
87	    const del = await gh(`/repos/${repo}/issues/${issue.number}/labels/${encodeURIComponent(ready)}`, { method: 'DELETE' });
88	    if (del.status >= 300) { log(`! could not un-label #${issue.number} to re-arm it: ${del.status}`); continue; }
89	    const add = await gh(`/repos/${repo}/issues/${issue.number}/labels`, { method: 'POST', body: { labels: [ready] } });
90	    if (add.status >= 300) log(`! re-arm of #${issue.number} dropped its ${ready} label: ${add.status}`);
91	    else { log(`re-armed #${issue.number} (${ready}) — its trigger event never landed`); result.rearmed.push(issue.number); }
92	  }
93	
94	  // The health review — the "reviews status, assesses health" half. Counts are
95	  // over the post-sweep label states as this run leaves them.
96	  const names = (i) => (i.labels ?? []).map((l) => (typeof l === 'string' ? l : l?.name)).filter(Boolean);
97	  const converged = new Set([...result.stale, ...result.deadClaims]);
98	  const armed = open.filter((i) => readyLabelOn(i) && !converged.has(i.number)).length;
99	  const running = open.filter((i) => names(i).includes(AGENT_RUNNING_LABEL) && !converged.has(i.number)).length;
100	  const needsHuman = open.filter((i) => names(i).includes(NEEDS_HUMAN_LABEL)).length + converged.size;
101	  log(`health: ${result.open} open dispatch issue(s) — ${armed} armed, ${running} running, ${needsHuman} needs-human; `
102	    + `this run escalated ${result.stale.length}, reclaimed ${result.deadClaims.length}, re-armed ${result.rearmed.length}`);
103	  return result;
104	}
105	
106	// WHICH SWEEP is the repo's dispatch mode (tasks-dispatch DESIGN §14): the two
107	// mechanisms have disjoint issue families, so a janitor that ran both sweeps would
108	// find nothing in one of them and a janitor that ran the wrong one would find
109	// nothing at all — and report a clean bill of health either way. One repo, one
110	// mechanism, one sweep.
111	export async function main() {
112	  const repo = process.env.CLAUDINITE_REPO || process.env.GITHUB_REPOSITORY;
113	  if (!repo) throw new Error('CLAUDINITE_REPO / GITHUB_REPOSITORY is not set (owner/repo)');
114	  if (!process.env.GITHUB_TOKEN) throw new Error('GITHUB_TOKEN is not set — the janitor cannot read or write issues');
115	  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
116	  const { loadConfig } = await import('../../../../engine/checks/helpers/repo-context.mjs');
117	  const config = loadConfig(root);
118	  const { sweepQueue } = await import('./queue-sweep.mjs');
119	  const { discoverTasks } = await import('../../../claudinite-tasks/discover.mjs');
120	  const { tasks } = await discoverTasks(root, config);
121	  await sweepQueue(makeGh(), repo, new Date(), { tasks, log });
122	  // The slot dispatch-issue sweep still runs BESIDE the queue's: the slot scheduler
123	  // is retired (#974) but the `[claudinite-task]` issues its last runs filed are
124	  // still open in members, and nothing else closes them out.
125	  await sweep(makeGh(), repo, new Date());
126	}
