1	// Does production exist yet? Answers that question and nothing else — it creates nothing,
2	// changes nothing, and is safe to run any number of times. What production is made of, and
3	// how each piece is asked about, is `cloudflare.ts`; this file is the report.
4	//
5	// Two jobs. Before the first deploy it turns "did I do every step?" into a green check —
6	// and every `MISS` it reports is something `npm run provision` creates. After the first
7	// deploy it is the first thing to run when a deploy fails, because most deploy failures are
8	// a resource or a secret that is not there.
9	import { readFileSync } from 'node:fs';
10	import { fileURLToPath } from 'node:url';
11	import {
12	  D1_DATABASE,
13	  PLACEHOLDER_DATABASE_ID,
14	  RESOURCES,
15	  accountRead,
16	  dashboardUrl,
17	  databaseIdIn,
18	  look,
19	  missing,
20	  present,
21	  unknown,
22	  type Result,
23	} from './cloudflare.ts';
24	
25	const WRANGLER_TOML = fileURLToPath(new URL('../../wrangler.toml', import.meta.url));
26	const SECRETS_SETTINGS = 'https://github.com/missingbulb/hitbut/settings/secrets/actions';
27	
28	type Check = {
29	  label: string;
30	  /** A failing optional check reports but does not fail the run — not everything is built yet. */
31	  required: boolean;
32	  why: string;
33	  /** Where to go to fix it: a dashboard page, a settings page, or the command that does it. */
34	  fix: string;
35	  run: () => Result | Promise<Result>;
36	};
37	
38	function fromEnvironment(name: string): Result {
39	  const value = process.env[name];
40	  return value ? present(`set (${value.length} characters)`) : missing('not set');
41	}
42	
43	function databaseIdPinned(): Result {
44	  const id = databaseIdIn(readFileSync(WRANGLER_TOML, 'utf8'));
45	  if (!id) return unknown('no database_id line in wrangler.toml — has the config changed shape?');
46	  return id === PLACEHOLDER_DATABASE_ID
47	    ? missing('still the all-zeros placeholder')
48	    : present(`pinned to ${id}`);
49	}
50	
51	/**
52	 * Where a deployed Worker can be reached. Without one `wrangler deploy` has nowhere to
53	 * publish to and asks interactively, which on a runner is a failure after the migrations
54	 * have already been applied. There is no `wrangler` command for it, so this reads the
55	 * account directly.
56	 */
57	async function workersDevSubdomain(): Promise<Result> {
58	  const read = await accountRead<{ subdomain?: string | null }>('workers/subdomain');
59	  if (!read.ok) return unknown(`could not ask the account — ${read.reason}`);
60	  return read.body?.subdomain
61	    ? present(`${read.body.subdomain}.workers.dev`)
62	    : missing('the account has never registered one');
63	}
64	
65	const CHECKS: Check[] = [
66	  {
67	    label: 'secret CLOUDFLARE_ACCOUNT_ID',
68	    required: true,
69	    why: 'nothing deploys without it, and every check below needs it',
70	    fix: `paste it at ${SECRETS_SETTINGS}`,
71	    run: () => fromEnvironment('CLOUDFLARE_ACCOUNT_ID'),
72	  },
73	  {
74	    label: 'secret CLOUDFLARE_API_TOKEN',
75	    required: true,
76	    why: 'nothing deploys without it, and every check below needs it',
77	    fix: `paste it at ${SECRETS_SETTINGS}`,
78	    run: () => fromEnvironment('CLOUDFLARE_API_TOKEN'),
79	  },
80	  {
81	    label: 'workers.dev subdomain',
82	    required: true,
83	    why: 'the Worker has nowhere to be published to, and wrangler asks for one interactively — which on a runner is a failed deploy, after the migrations have already been applied',
84	    fix: `register one at ${dashboardUrl('workers/onboarding', process.env.CLOUDFLARE_ACCOUNT_ID)} — one-time, and it names the Worker's host`,
85	    run: workersDevSubdomain,
86	  },
87	  {
88	    label: 'wrangler.toml database_id',
89	    required: true,
90	    why: 'the migrate step runs against this id; the placeholder is not a database',
91	    fix: 'the provision workflow reads the real id back and commits it',
92	    run: databaseIdPinned,
93	  },
94	  ...RESOURCES.map((resource) => ({
95	    label: resource.label,
96	    required: resource.required,
97	    why: resource.why,
98	    fix: `\`npm run provision\` creates it — or by hand at ${resource.dashboard(process.env.CLOUDFLARE_ACCOUNT_ID)}`,
99	    run: () => look(resource),
100	  })),
101	];
102	
103	const MARK: Record<Result['state'], string> = { present: 'ok  ', missing: 'MISS', unknown: '??  ' };
104	
105	const results = await Promise.all(CHECKS.map(async (check) => ({ check, result: await check.run() })));
106	
107	console.log('\nhitbut preflight — reads production, changes nothing\n');
108	for (const { check, result } of results) {
109	  console.log(`  [${MARK[result.state]}] ${check.label}`);
110	  console.log(`         ${result.detail}`);
111	  if (result.state !== 'present') {
