1	// The two operator levers (tasks-dispatch DESIGN §8), which are the whole of
2	// urgency, forcing, fan-out and retry:
3	//
4	//   create-work-item <pack>/<task> [--urgent] [--context …] [--not-before ISO]
5	//                                  [--blocked-by #N,#M] [--qualifier text]
6	//                                  [--supersedes #N]
7	//   create-work-item --wake <#N> [--urgent]
8	//
9	// FORCING A SCHEDULED TASK IS WAKING ITS STANDING ITEM — strip `task:blocked`,
10	// clear `Not-before`, optionally add `task:urgent`. The same lever as the human
11	// re-queue out of `needs-human`, which is no accident: "run this now" and "retry
12	// this now" are the same operation on the same object. The executor still
13	// evaluates the precondition at pick, so a force that finds no work SAYS so where
14	// the operator reads it. The slot scheduler's whole forcing apparatus — its override
15	// bag, the forced-verdict path, the `~f` slot marker and the watermark exclusion —
16	// reduced to these two levers and was deleted (#974).
17	//
18	// FORCING AD-HOC WORK IS CREATING AN ITEM — a parameterized run, a `manual` task,
19	// a fan-out target. Ad-hoc is STRUCTURAL (DESIGN §15.26): a `manual` task has no
20	// anchor to stand for, and a qualified title is a different title from the standing
21	// one — so such an item is invisible to the scheduler run's guards in both directions,
22	// neither suppressing tomorrow's occurrence nor consuming it. Which is why an
23	// UNQUALIFIED item for a scheduled task is refused below: it would BE that task's
24	// standing item, and the scheduler run's dedupe would close one of the two.
25	
26	import { pathToFileURL } from 'node:url';
27	import {
28	  READY, BLOCKED, URGENT, TASK_OBSOLETE, QUEUE_LABELS,
29	  EPISODE_MARKER, workItemTitle, workItemBody, withNotBefore, statusesOn,
30	} from './work-item.mjs';
31	import { clearStatus } from './apply-status.mjs';
32	
33	// The Context a hand-created item carries when the operator names none. Generic
34	// on purpose — it names the mechanism, not the task — because an item's Context is
35	// the agent's binding scope, and a forced item that carried none would read as a
36	// scope of nothing.
37	export const FORCED_CONTEXT =
38	  'Created by hand — no precondition asserts there is work to do. Do only what the task file specifies, and converge to a no-op if there is nothing.';
39	
40	export function parseArgs(argv) {
41	  const out = { urgent: false, context: [], blockedBy: [], notBefore: null, qualifier: null, supersedes: null, wake: null, target: null };
42	  for (let i = 0; i < argv.length; i += 1) {
43	    const a = argv[i];
44	    const next = () => argv[++i];
45	    if (a === '--urgent') out.urgent = true;
46	    else if (a === '--wake') out.wake = Number(String(next()).replace('#', ''));
47	    else if (a === '--context') out.context.push(next());
48	    else if (a === '--not-before') out.notBefore = next();
49	    else if (a === '--qualifier') out.qualifier = next();
50	    else if (a === '--supersedes') out.supersedes = Number(String(next()).replace('#', ''));
51	    else if (a === '--blocked-by') out.blockedBy.push(...String(next()).split(',').map((s) => Number(s.trim().replace('#', ''))).filter(Boolean));
52	    else if (!a.startsWith('--')) out.target = a;
53	  }
54	  return out;
55	}
56	
57	// Wake an item: clear its wait and put it back in the queue. Also the sanctioned
58	// road back from `needs-human` — nothing MECHANICAL ever re-queues a triage item,
59	// and the next pickup re-runs the precondition, which is what makes the retry safe
60	// even when the failed run half-did its work.
61	export async function wakeItem(gh, repo, number, { urgent = false } = {}) {
62	  const api = await import('../github.mjs');
63	  const issue = await api.readIssue(gh, repo, number);
64	  if (!issue) return { ok: false, error: `#${number} could not be read` };
65	  const body = withNotBefore(issue.body ?? '', null);
66	  if (body !== issue.body) await gh(`/repos/${repo}/issues/${number}`, { method: 'PATCH', body: { body } });
67	  // The episode boundary: every claim before this moment is dead, and arbitrating
68	  // over dead claims is what livelocks an item through reclaim cycles forever.
69	  await api.comment(gh, repo, number, `${EPISODE_MARKER}\nWoken by hand — cleared \`Not-before\` and returned this item to the queue.`);
70	  // Every status the item wears goes, in every spelling — a wake takes the item
71	  // back from whatever held it, and a park half-cleared (the state gone, its kind
72	  // still standing) is the torn shape the janitor would have to repair.
73	  for (const status of statusesOn(issue)) await clearStatus(api, gh, repo, issue, status);
74	  await api.addLabel(gh, repo, number, READY);
75	  if (urgent) await api.addLabel(gh, repo, number, URGENT);
76	  return { ok: true, number };
77	}
78	
79	export async function createWorkItem(gh, repo, { pack, task, taskPath, frequency = null, opts, log = console.log }) {
80	  const api = await import('../github.mjs');
81	  const { listOpenWorkItems } = await import('./read.mjs');
82	  const title = workItemTitle({ pack, task, qualifier: opts.qualifier });
83	
84	  // An unqualified item for a SCHEDULED task is that task's standing item by
85	  // construction, not a run beside it — the scheduler run would treat the pair as duplicate
86	  // standing items and close the younger. The two levers that do what the operator
87	  // meant are named rather than guessed at.
88	  if (frequency !== null && frequency !== 'manual' && !opts.qualifier) {
89	    return { ok: false, error: `${pack}/${task} runs on a \`${frequency}\` schedule, so an unqualified item for it IS its standing item — the scheduler run would close one of the two as a duplicate. To run it now, wake its standing item (\`--wake #N\`, or the scheduler workflow's \`wake\` input); to run it beside the schedule, give this item a \`--qualifier\` naming what makes it a different run.` };
90	  }
91	
92	  // The pick-time mutex means a new item QUEUES behind an open twin rather than
93	  // running beside it, and the operator should know they are queueing, not jumping.
94	  const twin = (await listOpenWorkItems(gh, repo)).find((i) => (i.title ?? '').trim() === title);
95	  if (twin) log(`! #${twin.number} is an open item with this exact title — the new item will queue behind it, not run beside it`);
96	
97	  await api.ensureLabels(gh, repo, QUEUE_LABELS);
98	  const blocked = opts.notBefore !== null || opts.blockedBy.length > 0;
99	  const res = await api.createIssue(gh, repo, {
100	    title,
101	    body: workItemBody({
102	      taskPath,
103	      notBefore: opts.notBefore,
104	      blockedBy: opts.blockedBy,
105	      context: opts.context.length ? opts.context : [FORCED_CONTEXT],
106	    }),
107	    labels: [blocked ? BLOCKED : READY, ...(opts.urgent ? [URGENT] : [])],
108	  });
