1	// What production is made of, and how to ask wrangler about it. One table, read by the
2	// preflight (which only looks) and by the provisioner (which creates what is missing), so
3	// the two cannot disagree about what production is or what a resource is called.
4	//
5	// The distinction the whole file works to preserve is **missing** versus **unknown**: a
6	// resource we asked about and were told does not exist, versus a question we could not ask
7	// because the token is wrong, the command moved, or the network refused. Reporting the
8	// second as the first sends someone to create something that is already there.
9	import { spawnSync } from 'node:child_process';
10	
11	export type State = 'present' | 'missing' | 'unknown';
12	export type Result = { state: State; detail: string };
13	
14	export const present = (detail: string): Result => ({ state: 'present', detail });
15	export const missing = (detail: string): Result => ({ state: 'missing', detail });
16	export const unknown = (detail: string): Result => ({ state: 'unknown', detail });
17	
18	export type Resource = {
19	  /** The name Cloudflare knows it by, and what the list output is searched for. */
20	  name: string;
21	  label: string;
22	  /** A failing optional check reports but does not fail the run — not everything is built yet. */
23	  required: boolean;
24	  why: string;
25	  /** Where a human would look at this in the dashboard, given an account id if we have one. */
26	  dashboard: (accountId?: string) => string;
27	  /** The wrangler arguments that list this kind of resource. */
28	  list: string[];
29	  /** The wrangler arguments that create this one, non-interactively. */
30	  create: string[];
31	};
32	
33	/** Where a human would look at one part of the account, given an id if we have one. */
34	export const dashboardUrl = (section: string, accountId?: string): string =>
