1	// Task discovery for the scheduler (per-project-scheduling DESIGN §3.2). One
2	// uniform scan of every ACTIVE pack's `tasks/<name>/task.mjs`, activation-gated
3	// by the repo's `packs` declaration exactly like checks and skills. Reuses the
4	// pack registry so the same scan works across all three layouts without knowing
5	// any of them: canon packs at `packs/`, a consumer's vendored canon at
6	// `.claudinite/shared/packs/`, and local packs at `.claudinite/local/packs/`
7	// (each pack carries its own resolved `dir`).
8	//
9	// Frequency filtering is deliberately NOT done here — discover returns every
10	// active, well-formed task; the scheduler run intersects them with the current anchors
11	// (queue/anchors.mjs). Keeping the two apart keeps each pure and separately
12	// testable. A task whose task.mjs fails to import or violates the declaration
13	// contract is dropped into `errors` (fail-soft, per-task), never sinking the
14	// scan.
15	
16	import { readdirSync, existsSync } from 'node:fs';
17	import { join, relative } from 'node:path';
18	import { pathToFileURL } from 'node:url';
19	import { loadPacks, isActive } from '../../engine/pack_loader/pack-registry.mjs';
20	import { normalizeTaskDeclaration, validateTaskDeclaration } from './task-contract.mjs';
21	import { BUILT_IN_PACK, builtInTasksRoot } from './built-in-tasks.mjs';
22	
23	// Discover every task the repo's active packs contribute. Returns
24	// `{ tasks, errors }` where each task is
25	// `{ pack, id, taskDir, taskPath, decl }` — `taskPath` is the repo-relative
26	// path to the worker file's directory's task.md (the work item's first
27	// line), `decl` the validated declaration.
28	export async function discoverTasks(root, config) {
29	  const errors = [];
30	  const packs = await loadPacks({ localRoot: root });
31	  const active = packs.filter((p) => isActive(p, config));
32	
33	  // The BUILT-IN root beside the pack scan (DESIGN §16.2). The engine ships one
34	  // task of its own — the request implementer — so a marked issue is an ordinary
35	  // run rather than a special item shape. It is not a pack and declares nothing:
36	  // wherever the queue runs, it is active, which is also what stops any pack
37	  // opting itself into the fields only it may declare.
38	  const roots = [...active.map((p) => ({ id: p.id, dir: join(p.dir, 'tasks') }))];
39	  const builtIn = builtInTasksRoot(root);
40	  if (builtIn) roots.push({ id: BUILT_IN_PACK, dir: builtIn });
41	
42	  const tasks = [];
43	  for (const pack of roots) {
44	    const tasksRoot = pack.dir;
45	    if (!existsSync(tasksRoot)) continue;
46	    let names;
47	    try {
48	      names = readdirSync(tasksRoot, { withFileTypes: true })
49	        .filter((d) => d.isDirectory()).map((d) => d.name).sort();
50	    } catch (e) {
51	      errors.push({ pack: pack.id, what: `${pack.id}'s tasks/ is not a readable directory: ${e.message}`, fix: `make ${relative(root, tasksRoot)} a directory (or remove it)` });
52	      continue;
53	    }
54	    for (const name of names) {
55	      const taskDir = join(tasksRoot, name);
56	      const mjs = join(taskDir, 'task.mjs');
57	      if (!existsSync(mjs)) continue;
58	      let decl;
59	      try {
60	        // Canonical field names from here on (legacy code-work names accepted at
61	        // the door, never re-checked downstream).
62	        decl = normalizeTaskDeclaration((await import(pathToFileURL(mjs).href)).default);
63	      } catch (e) {
64	        errors.push({ pack: pack.id, task: name, what: `${relative(root, mjs)} failed to import: ${e.message}`, fix: 'fix or remove the task' });
65	        continue;
66	      }
67	      const problems = validateTaskDeclaration(decl);
68	      if (problems.length) {
69	        errors.push({ pack: pack.id, task: name, what: `${relative(root, mjs)} is not a valid task declaration: ${problems.map((p) => p.what).join('; ')}`, fix: problems[0].fix });
70	        continue;
71	      }
72	      // A local pack's dir-name is its id (enforced by the registry); the task's
73	      // directory name should likewise match its declared id — a mismatch would
74	      // make the dispatch path and the declaration disagree.
75	      if (decl.id !== name) {
76	        errors.push({ pack: pack.id, task: name, what: `task in ${relative(root, taskDir)} declares id "${decl.id}" but its directory is "${name}"`, fix: 'rename the directory to the task id, or set the id to the directory name' });
77	        continue;
78	      }
79	      tasks.push({
80	        pack: pack.id,
81	        id: decl.id,
82	        taskDir,
83	        taskPath: `${relative(root, taskDir).split('\\').join('/')}/task.md`,
84	        decl,
85	      });
86	    }
87	  }
88	  return { tasks, errors };
89	}
